/** ProxySession is one session as the proxy serves it. */
export interface ProxySession {
  id: string;
  /** name.pier */
  host: string;
  ports: number[];
  /** the ports mirrored on localhost too */
  localhost: number[];
}

/** PushParams pushes a session's branch. */
export interface PushParams {
  sessionId: string;
  opId: string;
}

/** Question is one question the agent asks. */
export interface Question {
  /** ID keys the question's answer (the question itself, for claude). */
  id: string;
  question: string;
  /** a short chip: "Auth method" */
  header?: string;
  helper?: string;
  /** Kind: choice (pick from Options), text or number. */
  kind: string;
  options?: QuestionOption[];
  multiSelect?: boolean;
  placeholder?: string;
  /** Number questions: the range, step, starting value and unit. */
  min?: number;
  max?: number;
  step?: number;
  default?: number;
  unit?: string;
  /**
   * Other lets an answer be typed instead of picked; Secret hides it as
   * it is typed.
   */
  other?: boolean;
  secret?: boolean;
}

/** QuestionOption is one choice of a question. */
export interface QuestionOption {
  label: string;
  description?: string;
  /**
   * Preview is shown while the option is focused: markdown, or HTML when
   * PreviewHTML.
   */
  preview?: string;
  previewHtml?: boolean;
}

/** QueuedPrompt is a prompt the session holds until its agent can take it. */
export interface QueuedPrompt {
  id: string;
  text: string;
  attachments?: Attachment[];
  at: string;
}

/** Quota is the account's vCPU headroom in the active region. */
export interface Quota {
  used: number;
  limit: number;
  detail: string;
}

/** Regions are the regions (AWS) or zones (GCP) to pick from. */
export interface Regions {
  regions: string[];
}

/**
 * RegionsParams asks where sessions can run: AWS regions for a profile,
 * or GCP zones for a project.
 */
export interface RegionsParams {
  cloud: string;
  profile?: string;
  project?: string;
}

/** RenameWindowParams renames a window. */
export interface RenameWindowParams {
  sessionId: string;
  window: string;
  name: string;
}

/** Repo is one repository's row: its image, pool, sessions and idle cost. */
export interface Repo {
  name: string;
  origin?: string;
  /** the linked clone actions run from */
  checkout?: Checkout;
  /** the checkout carries a .pier/ directory */
  hasPier: boolean;
  image?: string;
  imageKind: ImageKind;
  bakedAt?: string;
  /** a bake started on this machine is still running */
  baking: boolean;
  /**
   * The pool: Target members kept, Ready parked and claimable, Filling
   * being set up, Stale about to recycle. Ages is one entry per member.
   */
  poolTarget: number;
  poolReady: number;
  poolFilling: number;
  poolStale: number;
  poolAges: string[];
  sessions: number;
  /** pooled disks plus image storage */
  monthlyUsd: number;
  /**
   * HourlyUSD is what the repo's sessions bill right now; IdleMonthlyUSD
   * what it costs while nothing runs: parked disks, the pool, the image.
   */
  hourlyUsd: number;
  idleMonthlyUsd: number;
  reminders: Reminder[];
}

/** ImageKind says what a repo's session image holds. */
export type ImageKind = "" | "prebuilt" | "toolchain" | "unknown";

/** Reminder is one piece of rebake guidance. pier never acts on it. */
export interface Reminder {
  message: string;
  action: string;
}

/** RepoRef names a repo by name. */
export interface RepoRef {
  repo: string;
}

/** ResizeParams changes a session's machine type. */
export interface ResizeParams {
  id: string;
  machineType: string;
}

/** Resources is a session's load. Sizes are bytes. */
export interface Resources {
  /** % of all CPUs */
  cpu: number;
  cpus: number;
  memUsed: number;
  memTotal: number;
  diskUsed: number;
  diskTotal: number;
  load1: number;
}

/**
 * SearchParams searches a session's checkout: literal text, or a regular
 * expression in ripgrep's syntax.
 */
export interface SearchParams {
  sessionId: string;
  query: string;
  regex?: boolean;
  caseSensitive?: boolean;
}

/**
 * SearchResult is a search's matches as they're found: the snapshot has
 * none, each event the next batch; the last says done (and why it
 * failed, if it did).
 */
export interface SearchResult {
  matches: SearchMatch[];
  truncated: boolean;
  done: boolean;
  error?: ErrorData;
}

/** SearchMatch is one line that matched. */
export interface SearchMatch {
  path: string;
  line: number;
  col: number;
  text: string;
}

/** Session is one session VM, or a pooled one waiting to be claimed. */
export interface Session {
  id: string;
  name: string;
  /** repo name (the checkout's folder name) */
  repo: string;
  /** canonical origin remote, host/owner/repo */
  origin?: string;
  /** origin branch the session came off */
  base?: string;
  branch: string;
  state: SessionState;
  /** one word for the row: starting, running, parked, … */
  label: string;
  /** what a running session is doing, "" when unknown */
  activity: string;
  attached: boolean;
  /** sustained cpu or memory pressure: a resize hint */
  strained: boolean;
  /** Setup is the repo setup script's state: "", "running" or "failed". */
  setup: string;
  machineType: string;
  /** "~$0.04/h" running, "~$3-4/mo" parked */
  costNote: string;
  /** 0 unless it bills compute right now */
  hourlyUsd: number;
  createdAt?: string;
  /** an unclaimed pool member, not a user session */
  pooled: boolean;
  /** this machine can reach it */
  hasKey: boolean;
  /** failed creates only */
  failReason?: string;
  /** failed creates: their create log */
  logPath?: string;
  /**
   * From the supervisor, while running: load, listening ports, and when it
   * stops on its own (parkAt while quiet and detached, capAt while it
   * works unattended).
   */
  resources?: Resources;
  ports?: Port[];
  parkAt?: string;
  capAt?: string;
  /** Chats are the session's agent chats, as last reported. */
  chats?: ChatSummary[];
  /** PR is the branch's pull request, when it has one. */
  pr?: PRSummary;
  /**
   * Attention says why the session needs the user, if it does:
   * needs_input, create_failed, setup_failed, ci_failing,
   * changes_requested, merged_cleanup or ready_to_merge.
   */
  attention?: string;
}

/** SessionRef names a session by id. */
export interface SessionRef {
  id: string;
}

/** SessionState is a session's lifecycle state. */
export type SessionState = "creating" | "running" | "working" | "idle" | "parked" | "deleting" | "dead" | "failed";

/** SettingParams sets one setting. */
export interface SettingParams {
  key: string;
  value: string;
}

/** Settings is the whole settings page. */
export interface Settings {
  groups: SettingGroup[];
  settings: Setting[];
}

/** Setting is one settings row: its schema and current value. */
export interface Setting {
  key: string;
  group: string;
  label: string;
  hint: string;
  /** multi-line explanation; `code` spans in backticks */
  detail: string;
  default: string;
  kind: SettingKind;
  options?: SettingOption[];
  noCustom: boolean;
  /** what an empty value reads as */
  empty?: string;
  /** unit shown after the value */
  suffix?: string;
  value: string;
  display: string;
}

/** SettingGroup is a settings page section, in page order. */
export interface SettingGroup {
  key: string;
  title: string;
}

/** SettingKind is how a setting is edited. */
export type SettingKind = "text" | "choice" | "machine";

/** SettingOption is one choice of a choice setting. */
export interface SettingOption {
  value: string;
  label: string;
  desc?: string;
}

/** SetupApplyParams finishes setup. */
export interface SetupApplyParams {
  draft: SetupDraft;
  /** Skills are the agent dirs to put the onboarding skill in. */
  skills: string[];
}

/** SetupCheckParams checks a cloud login. */
export interface SetupCheckParams {
  cloud: string;
  /** aws */
  profile?: string;
  /** gcp */
  project?: string;
  /** MFACode answers an AWS profile that asks for one (kind mfa_required). */
  mfaCode?: string;
}

/**
 * SetupDefaults is what a draft gives new sessions, and the machines to
 * pick from.
 */
export interface SetupDefaults {
  rows: DefaultRow[];
  machines: Machine[];
}

/** DefaultRow is one default new sessions get. */
export interface DefaultRow {
  key: string;
  label: string;
  value: string;
  note: string;
}

/**
 * SetupDraft is setup's answers: the cloud, its account, and the defaults
 * new sessions get.
 */
export interface SetupDraft {
  /** aws-ec2 | gcp-gce */
  cloud: string;
  awsProfile?: string;
  awsRegion?: string;
  /** AWSSubnet is for accounts without a default VPC. */
  awsSubnet?: string;
  gcpProject?: string;
  gcpZone?: string;
  machine: string;
  diskGib: number;
  idleTimeout: string;
  unattendedCap: string;
  /** fast | lean | minimal | custom */
  speed: string;
  manifest: string[];
  /** ClaudeToken is set only to change it; it is never read back. */
  claudeToken?: string;
}

/** SetupIdentity is who the login is, and the region the AWS profile uses. */
export interface SetupIdentity {
  identity: string;
  region?: string;
}

/** SetupResult is what setup did. */
export interface SetupResult {
  created: string[];
  existed: string[];
  checks: Check[];
  skills: string[];
  /** repo → session image found in the account */
  adopted: Record<string, string>;
}

/** SetupState is what setup finds on this machine before asking anything. */
export interface SetupState {
  configured: boolean;
  /** the saved answers, else the defaults */
  draft: SetupDraft;
  awsTools: SetupTool[];
  gcpTools: SetupTool[];
  /**
   * AWSProfiles are the AWS CLI's profiles; GCPAccount and GCPProject
   * gcloud's active login and project.
   */
  awsProfiles: string[];
  gcpAccount?: string;
  gcpProject?: string;
  /**
   * Agents are the agent config dirs here (".claude", ".codex"): the
   * onboarding skill can go into each.
   */
  agents: string[];
  /**
   * ClaudeAuth says how claude authenticates without a token, if it can;
   * NeedsClaudeToken that sessions need one (claude setup-token).
   */
  claudeAuth?: string;
  needsClaudeToken: boolean;
  hasClaudeToken: boolean;
}

/** SetupTool is a command-line tool setup needs. */
export interface SetupTool {
  name: string;
  /** how to install it */
  hint: string;
  found: boolean;
}

/** SubCancelParams ends a subscription (sub.cancel). */
export interface SubCancelParams {
  sub: string;
}

/**
 * SubEvent is one update of a subscription (sub.event). Seq increases by one
 * per event; a gap means the client missed one and should resubscribe.
 */
export interface SubEvent {
  sub: string;
  seq: number;
  topic: string;
  data: unknown;
}

/**
 * TermAck tells the server how much output the client has rendered
 * (term.ack). Output past an unacknowledged window waits, so a terminal
 * flooding output can't swamp the app; tmux absorbs the backlog.
 */
export interface TermAck {
  termId: string;
  bytes: number;
}

/**
 * TermCaptured says pier took something from a local terminal's output and
 * kept it (what: "claude-token", saved to pier's config).
 */
export interface TermCaptured {
  termId: string;
  what: string;
}

/**
 * TermData carries terminal bytes, base64-encoded: output in term.output
 * (Seq counts up per terminal), keystrokes in term.input.
 */
export interface TermData {
  termId: string;
  seq?: number;
  data: string;
}

/** TermExit says a terminal's process ended (term.exit). */
export interface TermExit {
  termId: string;
  code: number;
}

/** TermLocalParams opens a terminal on this machine. */
export interface TermLocalParams {
  purpose: LocalPurpose;
  /** Profile is the AWS profile an aws-sso login is for. */
  profile?: string;
  cols: number;
  rows: number;
}

/**
 * LocalPurpose names what a local terminal runs. The app never names a
 * command itself: pier decides what each purpose runs.
 */
export type LocalPurpose = "login" | "setup" | "aws-sso" | "gcloud-login" | "gh-login" | "claude-token";

/** TermOpenParams opens a terminal tab into a session's tmux. */
export interface TermOpenParams {
  sessionId: string;
  /** Window is the tmux window (@N) the tab shows; "" for main's current. */
  window?: string;
  cols: number;
  rows: number;
}

/** TermOpened is an open terminal. */
export interface TermOpened {
  termId: string;
}

/** TermRef names a terminal. */
export interface TermRef {
  termId: string;
}

/** TermSize resizes a terminal (term.resize). */
export interface TermSize {
  termId: string;
  cols: number;
  rows: number;
}

/** ToolCall is one tool call with its outcome. */
export interface ToolCall {
  id: string;
  name: string;
  view: ToolView;
  status: ToolStatus;
  /** Summary is the call in one line: the command, the file, the pattern. */
  summary: string;
  /** Input is the call's arguments as JSON, trimmed. */
  input?: string;
  /** trimmed */
  result?: string;
  truncated?: boolean;
  edit?: EditView;
  bash?: BashView;
  todos?: TodoItem[];
  /**
   * Questions and the answers given (by question text), for an ask;
   * Plan, markdown, for a plan.
   */
  questions?: Question[];
  answers?: Record<string, string>;
  plan?: string;
}

/** BashView is a command and its output. */
export interface BashView {
  command: string;
  description?: string;
  /** stdout then stderr, trimmed */
  output?: string;
  exitCode?: number;
}

/** EditView is a file change. */
export interface EditView {
  path: string;
  created?: boolean;
  hunks: Hunk[];
}

/** Hunk is a run of changed lines; each line starts with ' ', '-' or '+'. */
export interface Hunk {
  oldStart: number;
  oldLines: number;
  newStart: number;
  newLines: number;
  lines: string[];
}

/** TodoItem is one entry of the agent's task list. */
export interface TodoItem {
  content: string;
  /** pending | in_progress | completed */
  status: string;
}

/** ToolStatus is where a tool call is. */
export type ToolStatus = "running" | "ok" | "error" | "denied" | "interrupted";

/** ToolView is how a tool call is best shown. */
export type ToolView = "edit" | "write" | "bash" | "read" | "todo" | "search" | "web" | "task" | "ask" | "plan" | "generic";

/** Totals are the account-wide numbers the header shows. */
export interface Totals {
  /** includes starting */
  running: number;
  parked: number;
  poolReady: number;
  /** compute billing right now */
  hourlyUsd: number;
  /** parked disks, pools and images */
  idleMonthlyUsd: number;
}

/**
 * UploadParams puts a file attached to a prompt into a session. A parked
 * session's files wait on this Mac (the attachment's path starts with
 * "staged:") until the prompt wakes it.
 */
export interface UploadParams {
  sessionId: string;
  name: string;
  mime?: string;
  /** base64 */
  data: string;
}

/** Window is one tmux window of a session. */
export interface Window {
  /** @N, stable across renames */
  id: string;
  index: number;
  name: string;
  /** the active pane's foreground command */
  command: string;
  active: boolean;
  /** Role is what pier made the window for: "agent", "setup", or "". */
  role: string;
}

/** WindowParams names a session's window. */
export interface WindowParams {
  sessionId: string;
  window: string;
}

/** WindowRef names a tmux window of a session: a terminal tab opens on it. */
export interface WindowRef {
  windowId: string;
}

export const PROTOCOL_VERSION = 1;

/** Answer of a <topic>.watch: the subscription and its first data. */
export interface WatchResult<T> {
  sub: string;
  seq: number;
  snapshot: T;
}

/** Every request method: its params and result. */
export interface Methods {
  /** The account's vCPU quota use in the active region. */
  "account.headroom": { params: Empty; result: Quota };
  /** Removes pier from the account — every pooled session, the session images and the groundwork — narrating each step as progress. Sessions must be removed first. */
  "account.teardown": { params: Empty; result: null };
  /** What an agent offers — models with their efforts, permission modes — as a running session's agent says, else as last heard. */
  "agents.models": { params: ModelsParams; result: AgentModels };
  /** Runs the cloud login that fixes the last expired-login error, narrating its output (browser prompts, device codes) as progress. */
  "auth.login": { params: Empty; result: null };
  /** Stops a chat and puts it away. */
  "chat.close": { params: ChatRef; result: null };
  /** A prompt for the agent from the pull request — fixCI (with the failing logs), addressComments, createPR — for the composer, not sent. */
  "chat.compose": { params: ComposeParams; result: Composed };
  /** Changes a chat's model, effort, permission mode or title as it goes on. */
  "chat.configure": { params: ChatConfigureParams; result: null };
  /** Starts a chat in a session, once per chatId. A parked session is woken by a background job that starts it. */
  "chat.create": { params: ChatCreateParams; result: ChatCreated };
  /** Answers what a chat waits on: a tool use, its questions, its plan. */
  "chat.decide": { params: DecideParams; result: null };
  /** Takes back a prompt still waiting in a chat's queue. */
  "chat.dequeue": { params: DequeueParams; result: null };
  /** Older items of a chat, before the oldest one the client has. */
  "chat.history": { params: HistoryParams; result: HistoryPage };
  /** Stops a chat's turn. */
  "chat.interrupt": { params: ChatRef; result: null };
  /** Sends a prompt to a chat, once per prompt id. A parked session is woken by a background job that delivers it. */
  "chat.send": { params: ChatSendParams; result: ChatSendResult };
  /** Opens a terminal window in the session that continues a chat in its agent's own interface; the chat waits, and takes back what happens there when it exits. The result is the window to open a terminal tab on. */
  "chat.takeover": { params: ChatRef; result: WindowRef };
  /** A chat's conversation: the newest items, then changes as the agent writes them (text streams in as deltas). Parked sessions answer from this machine's copy. */
  "chat.watch": { params: ChatRef; result: WatchResult<ChatSnapshot> };
  /** A session's chats: their state, what they wait on, their queues. Parked sessions answer from this machine's copy. */
  "chats.watch": { params: SessionRef; result: WatchResult<ChatsSnapshot> };
  /** Opens the session's chats, live and read-only, in a terminal window of their own (made if missing); the result is the window to open a terminal tab on. */
  "chats.window": { params: SessionRef; result: WindowRef };
  /** Installs (or repairs) the pier command, a link to this app's pier; macOS asks for an administrator's password if needed — unless quiet, which then leaves it as it is. */
  "cli.install": { params: CLIInstallParams; result: CLIStatus };
  /** Whether the pier command in the shell is this app's pier: installed, provided another way (Homebrew), or a link left behind by a moved app. */
  "cli.status": { params: Empty; result: CLIStatus };
  /** Starts, stops or restarts one of a session's containers. */
  "containers.action": { params: ContainerParams; result: null };
  /** Checks the environment and the cloud account. */
  "doctor.run": { params: Empty; result: Check[] };
  /** What runs in a session — windows, containers, processes, ports, load — pushed every few seconds while watched. */
  "env.watch": { params: SessionRef; result: WatchResult<Env> };
  /** The paths in a session's checkout, tracked and untracked (ignored ones left out). A session that can't be read answers with the list this machine kept (asOf). */
  "files.list": { params: FileListParams; result: FileList };
  /** A file of a session's checkout (or, at base, as the branch's base has it), with the sha files.write checks against. A session that can't be read answers with the copy this machine kept of a changed file (asOf). */
  "files.read": { params: FileAtParams; result: FileContent };
  /** Puts a file attached to a prompt into a session; a parked session's waits on this Mac until the prompt wakes it. */
  "files.upload": { params: UploadParams; result: Attachment };
  /** Saves a file of a session's checkout, once per opId, unless it changed there since it was read (kind conflict). */
  "files.write": { params: FileWriteParams; result: FileWritten };
  /** Everything a session's branch changed against its base, committed or not. A parked session answers with what this machine last read. */
  "git.changes": { params: SessionRef; result: Changes };
  /** Commits everything in a session's checkout, once per opId. */
  "git.commit": { params: CommitParams; result: CommitResult };
  /** One changed file's unified diff against the base. */
  "git.diff": { params: DiffParams; result: FileDiff };
  /** Pushes a session's branch to origin, once per opId. */
  "git.push": { params: PushParams; result: null };
  /** Everything a session's branch changed against its base, pushed as it changes. A session that can't be read answers with what this machine kept (live false, asOf), and goes live once it can be. */
  "git.watch": { params: SessionRef; result: WatchResult<Changes> };
  /** Bakes the checkout's repo into a session image in a background job. */
  "image.bake": { params: BakeParams; result: Job };
  /** Opens the session: the protocol version both sides speak, and whether pier is set up. */
  "initialize": { params: InitializeParams; result: InitializeResult };
  /** A job's progress: every event so far, then each new one, ending with its done or failed event. */
  "job.watch": { params: JobRef; result: WatchResult<JobUpdate> };
  /** Stops a running job the way ctrl-c would, cleanup included. */
  "jobs.cancel": { params: JobRef; result: null };
  /** Background jobs this machine started, newest first (finished ones stay a day). */
  "jobs.list": { params: Empty; result: Job[] };
  /** The tail of a job's human log. */
  "jobs.log": { params: LogParams; result: LogText };
  /** The tail of a session's setup log (a failed create's own log for a create that never finished). */
  "logs.setup": { params: LogParams; result: LogText };
  /** The sidebar, Home and cockpit data, refreshed if older than a few seconds. */
  "overview.get": { params: Empty; result: Overview };
  /** The overview, pushed after every refresh. */
  "overview.watch": { params: Empty; result: WatchResult<Overview> };
  /** Destroys a repo's pooled sessions. */
  "pool.drain": { params: RepoRef; result: DrainResult };
  /** Tops up the checkout's repo pool now, in a background job. */
  "pool.fill": { params: PathParams; result: Job };
  /** Sets how many pooled sessions the checkout's repo keeps (0 turns the pool off and drains it). */
  "pool.setSize": { params: PoolSizeParams; result: null };
  /** Forwards a session's port to 127.0.0.1 on this Mac for as long as pier runs. */
  "ports.forward": { params: PortParams; result: null };
  /** The ports forwarded by hand. */
  "ports.list": { params: Empty; result: PortForward[] };
  /** Stops a port forward. */
  "ports.unforward": { params: PortParams; result: null };
  /** A session's pull request in full: checks, review threads, reviews. */
  "pr.get": { params: SessionRef; result: PRDetail };
  /** The end of a check's log (GitHub Actions). */
  "pr.log": { params: PRLogParams; result: LogText };
  /** Merges a session's pull request — only at the head that was reviewed (kind head_moved otherwise). */
  "pr.merge": { params: PRMergeParams; result: null };
  /** Re-runs a workflow run's failed jobs. */
  "pr.rerun": { params: PRRerunParams; result: null };
  /** The prompts pier sends agents (fix CI, address comments, create a PR, onboard, review comments) for a repo, or every repo: each with its own text, what it falls back to, and what is sent. */
  "prompts.get": { params: PromptsParams; result: Prompts };
  /** Sets a prompt for a repo, or every repo; empty text falls back again. */
  "prompts.set": { params: PromptSetParams; result: null };
  /** Stops the proxy and takes its network setup off this Mac (the .pier resolver, the boot task, the loopback addresses); macOS asks for an administrator's password. */
  "proxy.forget": { params: Empty; result: null };
  /** Serves every running session as <session>.pier with its ports mirrored on this Mac, from a background proxy shared with `pier proxy` that outlives the app. The first time, macOS asks for an administrator's password (local names and addresses, put back at every boot). */
  "proxy.start": { params: Empty; result: ProxyState };
  /** Stops the proxy, however it was started; sessions' names and mirrored ports go away. */
  "proxy.stop": { params: Empty; result: null };
  /** Makes this Mac trust the proxy's certificate, so https://<session>.pier opens without a warning (macOS asks for the password). */
  "proxy.trustCA": { params: Empty; result: null };
  /** The proxy's state, whoever started it: running, each session's name and mirrored ports. */
  "proxy.watch": { params: Empty; result: WatchResult<ProxyState> };
  /** What a create from the checkout containing path would carry: branch, HEAD, uncommitted changes, base. */
  "repos.inspect": { params: PathParams; result: CheckoutInfo };
  /** Links the repository containing path as a local checkout to act from. */
  "repos.link": { params: PathParams; result: Checkout };
  /** Forgets a linked checkout; the clone itself is untouched. */
  "repos.unlink": { params: PathParams; result: null };
  /** Finds text in a session's checkout (literal, or a regular expression), sending matches as they're found; the last event says done. */
  "search.watch": { params: SearchParams; result: WatchResult<SearchResult> };
  /** Starts a session from a linked checkout's HEAD (uncommitted edits travel too) in a background job. The row lists as starting until it is ready. */
  "sessions.create": { params: CreateParams; result: Job };
  /** Never parks this session when idle (it still stops on the runaway cap). */
  "sessions.keep": { params: SessionRef; result: null };
  /** The machine types a session can resize to: same CPU architecture, with shape and cost. */
  "sessions.machines": { params: SessionRef; result: Machine[] };
  /** Parks a running session now; its tmux layout is saved on the way down. */
  "sessions.park": { params: SessionRef; result: null };
  /** Destroys a session and its disk, or dismisses a failed create. */
  "sessions.remove": { params: SessionRef; result: null };
  /** Removes a session whose pull request merged — only when nothing in it is left behind: all committed, and the merged head is its head. */
  "sessions.removeMerged": { params: SessionRef; result: null };
  /** Changes a session's machine type in a background job: one park and resume, disk intact. */
  "sessions.resize": { params: ResizeParams; result: Job };
  /** Wakes a parked session and waits until it answers. */
  "sessions.resume": { params: SessionRef; result: null };
  /** The settings page: groups, fields and current values for the active cloud. */
  "settings.get": { params: Empty; result: Settings };
  /** The machine catalog the settings picker offers, around a current type. */
  "settings.machines": { params: MachinesParams; result: Machine[] };
  /** Validates and saves one setting, returning the page as it now reads. */
  "settings.set": { params: SettingParams; result: Settings };
  /** The commands an admin runs when the person setting pier up can't create its groundwork. */
  "setup.adminDoc": { params: CloudRef; result: LogText };
  /** Finishes setup: the account's groundwork, the config, the checks, the onboarding skill, the account's existing images. */
  "setup.apply": { params: SetupApplyParams; result: SetupResult };
  /** Checks a cloud login: who it is (and the AWS profile's region). An expired one fails with kind auth_expired and the login that fixes it. */
  "setup.check": { params: SetupCheckParams; result: SetupIdentity };
  /** What a draft gives new sessions, row by row with costs, and the machines to choose from. */
  "setup.defaults": { params: SetupDraft; result: SetupDefaults };
  /** What setup finds on this machine: tools, cloud logins, agent config, and the saved answers (else the defaults). */
  "setup.detect": { params: Empty; result: SetupState };
  /** Runs the login setup.check asked for — aws sso login for the profile, gcloud auth login — narrating it (browser prompts, device codes) as progress. */
  "setup.login": { params: SetupCheckParams; result: null };
  /** Where sessions can run: the AWS regions a profile's account has, or a GCP project's zones (the usual ones when the cloud can't be asked). */
  "setup.regions": { params: RegionsParams; result: Regions };
  /** Ends the server once every earlier request has answered and this reply is out. */
  "shutdown": { params: Empty; result: unknown };
  /** Hangs a terminal up. Its tmux windows keep running in the session. */
  "term.close": { params: TermRef; result: null };
  /** Opens a terminal tab into a session's tmux, on one of its windows. It counts as attached while open. */
  "term.open": { params: TermOpenParams; result: TermOpened };
  /** Opens a terminal on this machine for one of pier's interactive steps (a cloud login, setup). */
  "term.openLocal": { params: TermLocalParams; result: TermOpened };
  /** Closes a window and whatever runs in it. */
  "tmux.killWindow": { params: WindowParams; result: null };
  /** Adds a window in the session's checkout and returns it. */
  "tmux.newWindow": { params: NewWindowParams; result: Window };
  /** Renames a window. */
  "tmux.renameWindow": { params: RenameWindowParams; result: null };
  /** A session's tmux windows, in order. */
  "tmux.windows": { params: SessionRef; result: Window[] };
}

/** Every subscription topic: its watch params, its snapshot, and the data its events carry. */
export interface Watches {
  "chat": { params: ChatRef; snapshot: ChatSnapshot; data: ChatChange };
  "chats": { params: SessionRef; snapshot: ChatsSnapshot; data: ChatsChange };
  "env": { params: SessionRef; snapshot: Env; data: Env };
  "git": { params: SessionRef; snapshot: Changes; data: Changes };
  "job": { params: JobRef; snapshot: JobUpdate; data: JobUpdate };
  "overview": { params: Empty; snapshot: Overview; data: Overview };
  "proxy": { params: Empty; snapshot: ProxyState; data: ProxyState };
  "search": { params: SearchParams; snapshot: SearchResult; data: SearchResult };
}

export interface ServerNotifications {
  /** One progress event of a long request. */
  "$/progress": ProgressParams;
  /** Something about a session deserves the user's attention: a chat finished or needs them, its setup or create failed. Each id is sent once. */
  "notify": Notice;
  /** One update of a subscription. */
  "sub.event": SubEvent;
  /** pier took something a local terminal printed and kept it: the token `claude setup-token` made, saved to pier's config. */
  "term.captured": TermCaptured;
  /** A terminal's process ended. */
  "term.exit": TermExit;
  /** Terminal output, base64; acknowledge it with term.ack. */
  "term.output": TermData;
}

export interface ClientNotifications {
  /** Cancel an in-flight request. */
  "$/cancelRequest": CancelParams;
  /** Whether the client's window is focused, and what it shows. */
  "client.activity": ClientActivity;
  /** End a subscription. */
  "sub.cancel": SubCancelParams;
  /** How much terminal output the client has rendered. */
  "term.ack": TermAck;
  /** Keystrokes for a terminal, base64. */
  "term.input": TermData;
  /** Stop sending a hidden terminal's output. */
  "term.pause": TermRef;
  /** A terminal's new size. */
  "term.resize": TermSize;
  /** Send a terminal's output again. */
  "term.resume": TermRef;
}
